#include <iostream>
#include <string>

class CourseAccount {
public:
    // Constructor with validation
    explicit CourseAccount(const std::string& courseTitle) {
        setTitle(courseTitle);
    }

    // Mutator (Setter) with validation: truncate if title exceeds 12 chars
    void setTitle(const std::string& newTitle) {
        constexpr std::size_t maxChars = 12;
        if (newTitle.size() > maxChars) {
            title = newTitle.substr(0, maxChars);
        } else {
            title = newTitle;
        }
    }

    // Accessor (Getter): const inspector guarantees no state mutation
    std::string getTitle() const {
        return title;
    }

    // Const member function producing deterministic formatted output
    void displayInfo() const {
        std::cout << "Registered Course: " << getTitle() << "\n";
    }

private:
    std::string title{}; // Encapsulated private data member
};

int main() {
    // Create objects testing validation boundaries
    CourseAccount c1("Data Structures & Algorithms"); // Over 12 chars: truncated
    CourseAccount c2("Operating");                   // Within 12 chars

    c1.displayInfo();
    c2.displayInfo();

    // Mutate state
    c1.setTitle("DiscreteMath");
    std::cout << "Updated c1: " << c1.getTitle() << "\n";

    return 0;
}

#include <iostream>
#include <string>
#include <limits>

// ========================================================
// Component 1: Interface Simulation (Equivalent to Account.h)
// ========================================================
class BankAccount {
public:
    BankAccount() = default; // Explicitly defaulted constructor
    explicit BankAccount(int initialBalance); // Explicit 1-arg constructor

    void credit(int amount);
    void debit(int amount);
    int getBalance() const; // Inspector

private:
    int balance{0};
};

// ========================================================
// Component 2: Implementation Simulation (Account.cpp)
// ========================================================
// Member initializer list with scope resolution operator ::
BankAccount::BankAccount(int initialBalance)
    : balance{initialBalance >= 0 ? initialBalance : 0} {
    if (initialBalance < 0) {
        std::cout << "Error: Initial balance cannot be negative. Set to 0.\n";
    }
}

void BankAccount::credit(int amount) {
    if (amount > 0 && amount <= std::numeric_limits<int>::max() - balance) {
        balance += amount;
    }
}

void BankAccount::debit(int amount) {
    if (amount > balance) {
        std::cout << "Debit amount exceeded account balance.\n";
    } else if (amount > 0) {
        balance -= amount;
    }
}

int BankAccount::getBalance() const {
    return balance;
}

// ========================================================
// Component 3: Client Program (main.cpp)
// ========================================================
int main() {
    BankAccount acc1(150);
    BankAccount acc2(-40); // Triggers validation

    std::cout << "acc1 balance: $" << acc1.getBalance() << "\n";
    std::cout << "acc2 balance: $" << acc2.getBalance() << "\n";

    acc1.credit(50);
    std::cout << "acc1 after crediting 50: $" << acc1.getBalance() << "\n";

    acc1.debit(300); // Invalid debit: exceeds balance
    std::cout << "acc1 after invalid debit: $" << acc1.getBalance() << "\n";

    acc1.debit(80);  // Valid debit
    std::cout << "acc1 after valid debit: $" << acc1.getBalance() << "\n";

    return 0;
}
